package com.loopers.interfaces.api.payment;
import com.loopers.domain.payment.PaymentGateway;import com.loopers.infrastructure.payment.PgSimulatorPaymentGateway;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class PgSimulatorContractTest{@Test void stringOrderIdAndBothLookupRoutesAreCompatible(){PaymentGateway pg=new PgSimulatorPaymentGateway();PaymentGateway.Result created=null;for(int i=1;i<=5&&created==null;i++){String order="LP-SMOKE-%02d".formatted(i);try{created=pg.create("135135",new PaymentGateway.Request(order,"SAMSUNG","1234-1234-1234-1234",1000,"http://localhost:8080/callback"));}catch(RuntimeException ignored){}}assertThat(created).as("one of five bounded POSTs must reach the simulator").isNotNull();assertThat(created.orderId()).startsWith("LP-SMOKE-");assertThat(pg.findByTransactionKey("135135",created.transactionKey()).transactionKey()).isEqualTo(created.transactionKey());assertThat(pg.findByOrderId("135135",created.orderId())).isNotEmpty();}}
